    else:
        return _number2words(n)

def _number2words(n):
    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
    thousands = ["", "thousand", "million", "billion"]

    def helper(num, index):
        if num == 0:
            return ""
        elif num < 10:
            return units[num] + " "
        elif num < 20:
            return teens[num - 10] + " "
        elif num < 100:
            return tens[num // 10] + " " + helper(num % 10, 0)
        elif num < 1000:
            return units[num // 100] + " hundred " + helper(num % 100, 0)
        else:
            return helper(num // 1000, index + 1) + thousands[index] + " " + helper(num % 1000, 0)

    result = helper(n, 0)
    return result.strip()
