def number2words(n):
    if n == 0:
        return "zero"
    elif n < 0:
        return "negative " + number2words(-n)

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
    thousands = ["", "thousand", "million", "billion"]

    def helper(num, index):
        if num == 0:
            return ""
        elif num < 20:
            return units[num] + " " + thousands[index] + " "
        elif num < 100:
            return tens[num // 10] + "-" + units[num % 10] + " " + thousands[index] + " "
        else:
            return units[num // 100] + " hundred " + helper(num % 100, index) + " "

    result = ""
    i = 0
    while n > 0:
        if n % 1000 != 0:
            result = helper(n % 1000, i) + thousands[i] + " " + result
        n //= 1000
        i += 1

    return result.strip()
